<body>
<canvas id="c"></canvas>
<div class="cap"><b>The Great Wave off Kanagawa</b><br><span>low poly rebuild · Hokusai, c.1831 (public domain)</span></div>
<script type="module">
import * as THREE from 'three';

// ---- palette sampled from the print ----
const C = {
  sky:      0xe9dfc6, // aged washi cream
  skyGlow:  0xf4ecd6,
  blueDeep: 0x163a5e, // prussian / indigo body
  blueMid:  0x245a86,
  blueLite: 0x4d82ab,
  foam:     0xf4f1e6, // white foam
  boatTan:  0xc79a5b, // ochre deck
  boatDark: 0x2a1c10, // hull
  fujiBlue: 0x2c4d6e,
  fujiSnow: 0xf2efe4,
  figure:   0x1a1410,
};
const mat = (c, o={}) => new THREE.MeshStandardMaterial({ color:c, flatShading:true, roughness:.9, metalness:0, ...o });

const scene = new THREE.Scene();
scene.background = new THREE.Color(C.sky);
scene.fog = new THREE.Fog(C.sky, 9, 22);

const camera = new THREE.PerspectiveCamera(50, innerWidth/innerHeight, .1, 100);
camera.position.set(0, 1.3, 7.2);
camera.lookAt(0, 1.0, 0);

const renderer = new THREE.WebGLRenderer({ canvas:document.getElementById('c'), antialias:true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);

scene.add(new THREE.AmbientLight(0xfff4e0, .85));
const sun = new THREE.DirectionalLight(0xfff0d8, 1.1);
sun.position.set(4, 6, 5);
scene.add(sun);
const fill = new THREE.DirectionalLight(0xbcd2e8, .35);
fill.position.set(-5, 2, -3);
scene.add(fill);

// ---- swept low-poly ribbon (the curling wave body) ----
function makeSwept(profile, width, thickness, closed=true){
  const n = profile.length, pos = [], idx = [], tang = [];
  for (let i=0;i<n;i++){
    const p=profile[closed?(i-1+n)%n:Math.max(0,i-1)], q=profile[closed?(i+1)%n:Math.min(n-1,i+1)];
    let tx=q[0]-p[0], ty=q[1]-p[1]; const L=Math.hypot(tx,ty)||1;
    tang.push([tx/L, ty/L]);
  }
  for (let i=0;i<n;i++){
    const [x,y]=profile[i], [tx,ty]=tang[i], nx=-ty, ny=tx, hx=thickness/2, hw=width/2;
    pos.push(x+nx*hx,y+ny*hx,-hw, x+nx*hx,y+ny*hx,hw, x-nx*hx,y-ny*hx,hw, x-nx*hx,y-ny*hx,-hw);
  }
  const last = closed?n:n-1;
  for (let i=0;i<last;i++){
    const a=i*4, b=(i+1)*4;
    for (let c=0;c<4;c++){ const d=(c+1)%4; idx.push(a+c,a+d,b+d, a+c,b+d,b+c); }
  }
  const g=new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos,3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

// white foam "claws" along a crest
function addFoam(group, profile, thickness, indices, size){
  const up=new THREE.Vector3(0,1,0);
  const cone=new THREE.ConeGeometry(size, size*2.1, 6);
  const m=mat(C.foam);
  for (const i of indices){
    const [x,y]=profile[i];
    const p=profile[(i-1+profile.length)%profile.length], q=profile[(i+1)%profile.length];
    let tx=q[0]-p[0], ty=q[1]-p[1]; const L=Math.hypot(tx,ty)||1;
    const nx=-ty/L, ny=tx/L;
    const mesh=new THREE.Mesh(cone, m);
    mesh.position.set(x+nx*(thickness/2+size*.45), y+ny*(thickness/2+size*.45), 0);
    mesh.quaternion.setFromUnitVectors(up, new THREE.Vector3(nx,ny,0));
    group.add(mesh);
  }
}

